-- ===== ueno-otaki =====
-- 上野大滝線（ueno-otaki）の区間データ。tools/road.py build data/roads/ueno-otaki.json で生成。手で編集しない。
-- schema.sql を実行したあとに、SQL Editor で全文を実行する。何度実行しても同じ状態になる。
-- 出典：線：© OpenStreetMap contributors（ODbL）
-- 出典：線のうち埼玉県側：OSMの管理者タグ 埼玉県(秩父農林振興センター)
-- 出典：通行可否と規制：上野村「通行止めのお知らせ（令和8年9月2日現在）」。林道の問い合わせ先は上野村役場 振興課（埼玉県側の状況も同ページに記載）

set search_path = public, extensions;

insert into administrators (name, kind) values ('上野村', '市町村')
on conflict (name) do nothing;
insert into administrators (name, kind) values ('秩父農林振興センター', '県')
on conflict (name) do nothing;
insert into roads (name, kind) values ('上野大滝線', '林道')
on conflict (name) do nothing;

delete from segments where road_id = (select id from roads where name = '上野大滝線');

